INSERT INTO quiz_questions (
    id, quiz_id, question_type, prompt, difficulty, level, options, explanation, points, sort_order
) VALUES
    (gen_random_uuid(), NULL, 'multiple_choice', '________, how are you today?', 1, 'A1', '[{"key":"A","text":"hello","is_correct":true},{"key":"B","text":"tourist","is_correct":false},{"key":"C","text":"blanket","is_correct":false},{"key":"D","text":"jacket","is_correct":false}]'::jsonb, 'Đáp án đúng là A (hello - xin chào). Dịch câu: "Xin chào, hôm nay bạn thế nào?". Các lựa chọn khác: tourist: khách du lịch; blanket: chiếc chăn; jacket: áo khoác ngắn.', 10, 1),
    (gen_random_uuid(), NULL, 'multiple_choice', '________, see you tomorrow!', 2, 'A1', '[{"key":"A","text":"pencil","is_correct":false},{"key":"B","text":"friend","is_correct":false},{"key":"C","text":"goodbye","is_correct":true},{"key":"D","text":"uncle","is_correct":false}]'::jsonb, 'Đáp án đúng là C (goodbye - tạm biệt). Dịch câu: "Tạm biệt, hẹn gặp lại bạn vào ngày mai!". Các lựa chọn khác: pencil: bút chì; friend: người bạn; uncle: chú, bác, cậu.', 10, 2),
    (gen_random_uuid(), NULL, 'multiple_choice', '________ open the window.', 3, 'A1', '[{"key":"A","text":"please","is_correct":true},{"key":"B","text":"sometimes","is_correct":false},{"key":"C","text":"therefore","is_correct":false},{"key":"D","text":"however","is_correct":false}]'::jsonb, 'Đáp án đúng là A (please - làm ơn, vui lòng). Dịch câu: "Làm ơn mở cửa sổ ra.". Các lựa chọn khác: sometimes: thỉnh thoảng, đôi khi (40%); therefore: do đó, vì vậy; however: tuy nhiên.', 10, 3),
    (gen_random_uuid(), NULL, 'multiple_choice', 'I want to ________ you for your help.', 1, 'A1', '[{"key":"A","text":"reply","is_correct":false},{"key":"B","text":"call","is_correct":false},{"key":"C","text":"thank","is_correct":true},{"key":"D","text":"rest","is_correct":false}]'::jsonb, 'Đáp án đúng là C (thank - cảm ơn). Dịch câu: "Tôi muốn cảm ơn bạn vì sự giúp đỡ.". Các lựa chọn khác: reply: trả lời, phản hồi; call: gọi điện, gọi tên; rest: nghỉ ngơi, tĩnh dưỡng.', 10, 4),
    (gen_random_uuid(), NULL, 'multiple_choice', 'You are always ________ here.', 2, 'A1', '[{"key":"A","text":"polite","is_correct":false},{"key":"B","text":"pink","is_correct":false},{"key":"C","text":"expensive","is_correct":false},{"key":"D","text":"welcome","is_correct":true}]'::jsonb, 'Đáp án đúng là D (welcome - được chào đón, không có chi). Dịch câu: "Bạn luôn được chào đón ở đây.". Các lựa chọn khác: polite: lịch sự, lễ phép; pink: màu hồng; expensive: đắt đỏ, tốn kém.', 10, 5),
    (gen_random_uuid(), NULL, 'multiple_choice', 'I am ________ for being late.', 3, 'A1', '[{"key":"A","text":"clever","is_correct":false},{"key":"B","text":"blue","is_correct":false},{"key":"C","text":"busy","is_correct":false},{"key":"D","text":"sorry","is_correct":true}]'::jsonb, 'Đáp án đúng là D (sorry - xin lỗi, lấy làm tiếc). Dịch câu: "Tôi xin lỗi vì đã đến muộn.". Các lựa chọn khác: clever: thông minh, khéo léo; blue: màu xanh lam, xanh nước biển; busy: bận rộn.', 10, 6),
    (gen_random_uuid(), NULL, 'multiple_choice', '________ me, where is the station?', 1, 'A1', '[{"key":"A","text":"thank","is_correct":false},{"key":"B","text":"excuse","is_correct":true},{"key":"C","text":"agree","is_correct":false},{"key":"D","text":"swim","is_correct":false}]'::jsonb, 'Đáp án đúng là B (excuse - thứ lỗi, xin phép). Dịch câu: "Xin lỗi, nhà ga ở đâu vậy?". Các lựa chọn khác: thank: cảm ơn; agree: đồng ý; swim: bơi lội.', 10, 7),
    (gen_random_uuid(), NULL, 'multiple_choice', 'My ________ is Linh.', 2, 'A1', '[{"key":"A","text":"morning","is_correct":false},{"key":"B","text":"name","is_correct":true},{"key":"C","text":"chef","is_correct":false},{"key":"D","text":"hand","is_correct":false}]'::jsonb, 'Đáp án đúng là B (name - tên). Dịch câu: "Tên của tôi là Linh.". Các lựa chọn khác: morning: buổi sáng; chef: đầu bếp trưởng; hand: bàn tay.', 10, 8),
    (gen_random_uuid(), NULL, 'multiple_choice', 'Nice to ________ you.', 3, 'A1', '[{"key":"A","text":"tell","is_correct":false},{"key":"B","text":"borrow","is_correct":false},{"key":"C","text":"shout","is_correct":false},{"key":"D","text":"meet","is_correct":true}]'::jsonb, 'Đáp án đúng là D (meet - gặp, gặp gỡ). Dịch câu: "Rất vui được gặp bạn.". Các lựa chọn khác: tell: kể, bảo; borrow: vay, mượn; shout: hét lên, la lớn.', 10, 9),
    (gen_random_uuid(), NULL, 'multiple_choice', 'Do you ________ English?', 1, 'A1', '[{"key":"A","text":"speak","is_correct":true},{"key":"B","text":"call","is_correct":false},{"key":"C","text":"cost","is_correct":false},{"key":"D","text":"lose","is_correct":false}]'::jsonb, 'Đáp án đúng là A (speak - nói (ngôn ngữ)). Dịch câu: "Bạn có nói tiếng Anh không?". Các lựa chọn khác: call: gọi điện, gọi tên; cost: có giá là, tốn phí; lose: thua cuộc, mất.', 10, 10),
    (gen_random_uuid(), NULL, 'multiple_choice', 'We ________ on the phone every night.', 2, 'A1', '[{"key":"A","text":"lend","is_correct":false},{"key":"B","text":"talk","is_correct":true},{"key":"C","text":"visit","is_correct":false},{"key":"D","text":"jump","is_correct":false}]'::jsonb, 'Đáp án đúng là B (talk - nói chuyện, trò chuyện). Dịch câu: "Chúng tôi trò chuyện qua điện thoại mỗi tối.". Các lựa chọn khác: lend: cho vay, cho mượn; visit: thăm quan, ghé thăm; jump: nhảy, bật nhảy.', 10, 11),
    (gen_random_uuid(), NULL, 'multiple_choice', '________ carefully to the teacher.', 3, 'A1', '[{"key":"A","text":"spend","is_correct":false},{"key":"B","text":"understand","is_correct":false},{"key":"C","text":"fail","is_correct":false},{"key":"D","text":"listen","is_correct":true}]'::jsonb, 'Đáp án đúng là D (listen - lắng nghe). Dịch câu: "Hãy lắng nghe giáo viên cẩn thận.". Các lựa chọn khác: spend: tiêu xài, dành (thời gian); understand: hiểu; fail: thi trượt, thất bại.', 10, 12),
    (gen_random_uuid(), NULL, 'multiple_choice', 'I do not ________ this question.', 1, 'A1', '[{"key":"A","text":"understand","is_correct":true},{"key":"B","text":"sell","is_correct":false},{"key":"C","text":"speak","is_correct":false},{"key":"D","text":"say","is_correct":false}]'::jsonb, 'Đáp án đúng là A (understand - hiểu). Dịch câu: "Tôi không hiểu câu hỏi này.". Các lựa chọn khác: sell: bán hàng; speak: nói (ngôn ngữ); say: nói rằng.', 10, 13),
    (gen_random_uuid(), NULL, 'multiple_choice', 'Could you ________ that, please?', 2, 'A1', '[{"key":"A","text":"meet","is_correct":false},{"key":"B","text":"agree","is_correct":false},{"key":"C","text":"repeat","is_correct":true},{"key":"D","text":"brush","is_correct":false}]'::jsonb, 'Đáp án đúng là C (repeat - lặp lại, nhắc lại). Dịch câu: "Bạn có thể nhắc lại điều đó được không?". Các lựa chọn khác: meet: gặp, gặp gỡ; agree: đồng ý; brush: chải (tóc, răng).', 10, 14),
    (gen_random_uuid(), NULL, 'multiple_choice', 'Can you ________ me with my luggage?', 3, 'A1', '[{"key":"A","text":"help","is_correct":true},{"key":"B","text":"buy","is_correct":false},{"key":"C","text":"read","is_correct":false},{"key":"D","text":"sleep","is_correct":false}]'::jsonb, 'Đáp án đúng là A (help - giúp đỡ). Dịch câu: "Bạn có thể giúp tôi với hành lý này không?". Các lựa chọn khác: buy: mua sắm; read: đọc; sleep: ngủ.', 10, 15),
    (gen_random_uuid(), NULL, 'multiple_choice', 'How do you ________ your last name?', 1, 'A1', '[{"key":"A","text":"spell","is_correct":true},{"key":"B","text":"draw","is_correct":false},{"key":"C","text":"call","is_correct":false},{"key":"D","text":"meet","is_correct":false}]'::jsonb, 'Đáp án đúng là A (spell - đánh vần). Dịch câu: "Bạn đánh vần họ của mình như thế nào?". Các lựa chọn khác: draw: vẽ (bằng bút chì, nét vẽ); call: gọi điện, gọi tên; meet: gặp, gặp gỡ.', 10, 16),
    (gen_random_uuid(), NULL, 'multiple_choice', 'Let me ________ my friend to you.', 2, 'A1', '[{"key":"A","text":"introduce","is_correct":true},{"key":"B","text":"clean","is_correct":false},{"key":"C","text":"work","is_correct":false},{"key":"D","text":"thank","is_correct":false}]'::jsonb, 'Đáp án đúng là A (introduce - giới thiệu). Dịch câu: "Để tôi giới thiệu bạn của tôi với bạn.". Các lựa chọn khác: clean: dọn dẹp, lau chùi; work: làm việc, công tác; thank: cảm ơn.', 10, 17),
    (gen_random_uuid(), NULL, 'multiple_choice', 'She is my best ________.', 3, 'A1', '[{"key":"A","text":"park","is_correct":false},{"key":"B","text":"customer","is_correct":false},{"key":"C","text":"friend","is_correct":true},{"key":"D","text":"card","is_correct":false}]'::jsonb, 'Đáp án đúng là C (friend - người bạn). Dịch câu: "Cô ấy là bạn thân nhất của tôi.". Các lựa chọn khác: park: công viên; customer: khách hàng; card: thẻ ngân hàng, thẻ từ.', 10, 18),
    (gen_random_uuid(), NULL, 'multiple_choice', 'What is the correct English word for "câu hỏi" (noun)?', 1, 'A1', '[{"key":"A","text":"film","is_correct":false},{"key":"B","text":"chicken","is_correct":false},{"key":"C","text":"coffee","is_correct":false},{"key":"D","text":"question","is_correct":true}]'::jsonb, 'Đáp án đúng là D (question - câu hỏi). Dịch câu: "Bạn có câu hỏi nào không?". Các lựa chọn khác: film: phim điện ảnh; chicken: thịt gà, con gà; coffee: cà phê.', 10, 19),
    (gen_random_uuid(), NULL, 'multiple_choice', 'Write your ________ on the paper.', 2, 'A1', '[{"key":"A","text":"foot","is_correct":false},{"key":"B","text":"boat","is_correct":false},{"key":"C","text":"bridge","is_correct":false},{"key":"D","text":"answer","is_correct":true}]'::jsonb, 'Đáp án đúng là D (answer - câu trả lời). Dịch câu: "Hãy viết câu trả lời của bạn vào giấy.". Các lựa chọn khác: foot: bàn chân; boat: thuyền, đò; bridge: cây cầu.', 10, 20),
    (gen_random_uuid(), NULL, 'multiple_choice', 'You can ________ the teacher for advice.', 3, 'A1', '[{"key":"A","text":"ask","is_correct":true},{"key":"B","text":"order","is_correct":false},{"key":"C","text":"tell","is_correct":false},{"key":"D","text":"say","is_correct":false}]'::jsonb, 'Đáp án đúng là A (ask - hỏi, yêu cầu). Dịch câu: "Bạn có thể hỏi xin giáo viên lời khuyên.". Các lựa chọn khác: order: gọi món, đặt hàng; tell: kể, bảo; say: nói rằng.', 10, 21),
    (gen_random_uuid(), NULL, 'multiple_choice', 'He did not ________ to my email.', 1, 'A1', '[{"key":"A","text":"shout","is_correct":false},{"key":"B","text":"fire","is_correct":false},{"key":"C","text":"reply","is_correct":true},{"key":"D","text":"ask","is_correct":false}]'::jsonb, 'Đáp án đúng là C (reply - trả lời, phản hồi). Dịch câu: "Anh ấy đã không phản hồi email của tôi.". Các lựa chọn khác: shout: hét lên, la lớn; fire: sa thải, đuổi việc; ask: hỏi, yêu cầu.', 10, 22),
    (gen_random_uuid(), NULL, 'multiple_choice', 'Can you ________ this rule again?', 2, 'A1', '[{"key":"A","text":"work","is_correct":false},{"key":"B","text":"cost","is_correct":false},{"key":"C","text":"buy","is_correct":false},{"key":"D","text":"explain","is_correct":true}]'::jsonb, 'Đáp án đúng là D (explain - giải thích). Dịch câu: "Bạn có thể giải thích lại quy tắc này được không?". Các lựa chọn khác: work: làm việc, công tác; cost: có giá là, tốn phí; buy: mua sắm.', 10, 23),
    (gen_random_uuid(), NULL, 'multiple_choice', 'What is the ________ of this word?', 3, 'A1', '[{"key":"A","text":"email","is_correct":false},{"key":"B","text":"meaning","is_correct":true},{"key":"C","text":"trip","is_correct":false},{"key":"D","text":"sister","is_correct":false}]'::jsonb, 'Đáp án đúng là B (meaning - ý nghĩa). Dịch câu: "Ý nghĩa của từ này là gì?". Các lựa chọn khác: email: thư điện tử; trip: chuyến đi, chuyến du ngoạn; sister: chị gái, em gái.', 10, 24),
    (gen_random_uuid(), NULL, 'multiple_choice', 'English is a global ________.', 1, 'A1', '[{"key":"A","text":"pillow","is_correct":false},{"key":"B","text":"arm","is_correct":false},{"key":"C","text":"clock","is_correct":false},{"key":"D","text":"language","is_correct":true}]'::jsonb, 'Đáp án đúng là D (language - ngôn ngữ, tiếng). Dịch câu: "Tiếng Anh là một ngôn ngữ toàn cầu.". Các lựa chọn khác: pillow: chiếc gối; arm: cánh tay; clock: đồng hồ treo tường.', 10, 25),
    (gen_random_uuid(), NULL, 'multiple_choice', 'Please ________ me after 6 PM.', 2, 'A1', '[{"key":"A","text":"wake","is_correct":false},{"key":"B","text":"repeat","is_correct":false},{"key":"C","text":"call","is_correct":true},{"key":"D","text":"jump","is_correct":false}]'::jsonb, 'Đáp án đúng là C (call - gọi điện, gọi tên). Dịch câu: "Vui lòng gọi cho tôi sau 6 giờ tối.". Các lựa chọn khác: wake: thức dậy, đánh thức; repeat: lặp lại, nhắc lại; jump: nhảy, bật nhảy.', 10, 26),
    (gen_random_uuid(), NULL, 'multiple_choice', 'I sent you a text ________.', 3, 'A1', '[{"key":"A","text":"message","is_correct":true},{"key":"B","text":"hill","is_correct":false},{"key":"C","text":"shoe","is_correct":false},{"key":"D","text":"sock","is_correct":false}]'::jsonb, 'Đáp án đúng là A (message - tin nhắn). Dịch câu: "Tôi đã gửi cho bạn một tin nhắn văn bản.". Các lựa chọn khác: hill: ngọn đồi; shoe: chiếc giày; sock: chiếc tất, vớ.', 10, 27),
    (gen_random_uuid(), NULL, 'multiple_choice', 'Check your ________ for confirmation.', 1, 'A1', '[{"key":"A","text":"river","is_correct":false},{"key":"B","text":"email","is_correct":true},{"key":"C","text":"receipt","is_correct":false},{"key":"D","text":"key","is_correct":false}]'::jsonb, 'Đáp án đúng là B (email - thư điện tử). Dịch câu: "Kiểm tra email của bạn để xác nhận.". Các lựa chọn khác: river: con sông; receipt: biên lai, hóa đơn thu tiền; key: chìa khóa.', 10, 28),
    (gen_random_uuid(), NULL, 'multiple_choice', 'We had a long ________ about books.', 2, 'A1', '[{"key":"A","text":"card","is_correct":false},{"key":"B","text":"conversation","is_correct":true},{"key":"C","text":"driver","is_correct":false},{"key":"D","text":"finger","is_correct":false}]'::jsonb, 'Đáp án đúng là B (conversation - cuộc trò chuyện). Dịch câu: "Chúng tôi đã có một cuộc trò chuyện dài về sách.". Các lựa chọn khác: card: thẻ ngân hàng, thẻ từ; driver: tài xế, người lái xe; finger: ngón tay.', 10, 29),
    (gen_random_uuid(), NULL, 'multiple_choice', 'I totally ________ with your idea.', 3, 'A1', '[{"key":"A","text":"work","is_correct":false},{"key":"B","text":"understand","is_correct":false},{"key":"C","text":"agree","is_correct":true},{"key":"D","text":"write","is_correct":false}]'::jsonb, 'Đáp án đúng là C (agree - đồng ý). Dịch câu: "Tôi hoàn toàn đồng ý với ý kiến của bạn.". Các lựa chọn khác: work: làm việc, công tác; understand: hiểu; write: viết.', 10, 30),
    (gen_random_uuid(), NULL, 'multiple_choice', 'They ________ on the final plan.', 1, 'A1', '[{"key":"A","text":"read","is_correct":false},{"key":"B","text":"ask","is_correct":false},{"key":"C","text":"introduce","is_correct":false},{"key":"D","text":"disagree","is_correct":true}]'::jsonb, 'Đáp án đúng là D (disagree - không đồng ý). Dịch câu: "Họ không đồng ý về kế hoạch cuối cùng.". Các lựa chọn khác: read: đọc; ask: hỏi, yêu cầu; introduce: giới thiệu.', 10, 31),
    (gen_random_uuid(), NULL, 'multiple_choice', 'What did he ________ to you?', 2, 'A1', '[{"key":"A","text":"say","is_correct":true},{"key":"B","text":"sell","is_correct":false},{"key":"C","text":"explain","is_correct":false},{"key":"D","text":"call","is_correct":false}]'::jsonb, 'Đáp án đúng là A (say - nói rằng). Dịch câu: "Anh ấy đã nói gì với bạn?". Các lựa chọn khác: sell: bán hàng; explain: giải thích; call: gọi điện, gọi tên.', 10, 32),
    (gen_random_uuid(), NULL, 'multiple_choice', '________ me the truth.', 3, 'A1', '[{"key":"A","text":"explain","is_correct":false},{"key":"B","text":"tell","is_correct":true},{"key":"C","text":"sing","is_correct":false},{"key":"D","text":"cook","is_correct":false}]'::jsonb, 'Đáp án đúng là B (tell - kể, bảo). Dịch câu: "Hãy nói cho tôi biết sự thật.". Các lựa chọn khác: explain: giải thích; sing: hát, ca hát; cook: nấu ăn, nấu nướng.', 10, 33),
    (gen_random_uuid(), NULL, 'multiple_choice', 'Don''''t ________ in the library.', 1, 'A1', '[{"key":"A","text":"help","is_correct":false},{"key":"B","text":"tell","is_correct":false},{"key":"C","text":"shout","is_correct":true},{"key":"D","text":"meet","is_correct":false}]'::jsonb, 'Đáp án đúng là C (shout - hét lên, la lớn). Dịch câu: "Đừng hét lên trong thư viện.". Các lựa chọn khác: help: giúp đỡ; tell: kể, bảo; meet: gặp, gặp gỡ.', 10, 34),
    (gen_random_uuid(), NULL, 'multiple_choice', 'What is the correct English word for "nói thì thầm" (verb)?', 2, 'A1', '[{"key":"A","text":"reply","is_correct":false},{"key":"B","text":"teach","is_correct":false},{"key":"C","text":"forget","is_correct":false},{"key":"D","text":"whisper","is_correct":true}]'::jsonb, 'Đáp án đúng là D (whisper - nói thì thầm). Dịch câu: "Cô ấy thì thầm một bí mật vào tai tôi.". Các lựa chọn khác: reply: trả lời, phản hồi; teach: dạy học, giảng dạy; forget: quên.', 10, 35),
